import json, hashlib, hmac
base = '/opt/crypto-case/'
def load(p): return json.load(open(base + p))
def loadl(p): return [json.loads(x) for x in open(base + p)]

estate = load('case/estate.json')
materials = load('case/materials.json')['materials']
policy = load('case/policy-baseline.json')
events = loadl('case/deployment-events.jsonl')

# Compromised and retire materials
compromised = ['sign-release-rsa']
retire = [m['id'] for m in materials if m.get('disposition') == 'retire_at_completion']

# Dependencies
deps = []
bound_subjects = {}
for e in events:
    if e['time'] <= estate['captured_at']:
        if e['event'] == 'bind':
            bound_subjects[e['subject']] = e['consumer']
        elif e['event'] == 'unbind':
            if e['subject'] in bound_subjects:
                del bound_subjects[e['subject']]

tls_obs = loadl('case/tls-negotiations.jsonl')
sign_obs = loadl('case/signature-verifications.jsonl')
ssh_obs = loadl('case/ssh-sessions.jsonl')

latest_obs = {}
for obs in tls_obs + sign_obs + ssh_obs:
    if obs.get('result') == 'success' and obs['observed_at'] <= estate['captured_at']:
        subj = obs['subject']
        if subj in bound_subjects:
            if subj not in latest_obs or obs['observed_at'] > latest_obs[subj]['observed_at']:
                latest_obs[subj] = obs

consumer_deps = {}
for subj, obs in latest_obs.items():
    cons = bound_subjects[subj]
    if cons not in consumer_deps:
        consumer_deps[cons] = {'surface': obs['surface'], 'consumer': cons, 'effective_algorithms': set(), 'materials': set(), 'evidence': set()}
    consumer_deps[cons]['effective_algorithms'].update(obs['algorithms'])
    consumer_deps[cons]['materials'].update(obs.get('materials', []))
    consumer_deps[cons]['evidence'].add(obs['id'])

for v in consumer_deps.values():
    deps.append({
        'surface': v['surface'],
        'consumer': v['consumer'],
        'effective_algorithms': sorted(list(v['effective_algorithms'])),
        'materials': sorted(list(v['materials'])),
        'evidence': sorted(list(v['evidence']))
    })

archives = load('case/archives.json')['archives']
for a in archives:
    deps.append({
        'surface': a['surface'],
        'consumer': a['id'],
        'effective_algorithms': sorted([a['data_cipher'], a['wrap_algorithm']]),
        'materials': [a['wrap_material']],
        'evidence': [a['evidence']]
    })

final_policies = {
    'tls:telemetry-api': {
        'minimum_protocol': policy['surfaces']['tls:telemetry-api']['minimum_protocol'],
        'allowed_kex': policy['surfaces']['tls:telemetry-api']['required_kex'],
        'allowed_server_credentials': ['tls-api-2027'],
        'trusted_roots': ['tls-root-2027'],
