        'allowed_algorithms': policy['surfaces']['signing:device-update']['allowed_signature_algorithms'],
        'threshold': policy['surfaces']['signing:device-update']['threshold'],
        'context': policy['surfaces']['signing:device-update']['signing_context'],
        'reject_revoked': policy['surfaces']['signing:device-update']['reject_revoked']
    },
    'ssh:ops-bastion': {
        'allowed_host_algorithms': policy['surfaces']['ssh:ops-bastion']['allowed_host_key_algorithms'],
        'allowed_user_ca_algorithms': policy['surfaces']['ssh:ops-bastion']['allowed_user_ca_algorithms'],
        'allowed_host_keys': ['ssh-host-ed25519-c'],
        'trusted_user_cas': ['ssh-user-ca-ed'],
        'reject_sha1': policy['surfaces']['ssh:ops-bastion']['reject_sha1'],
        'strict_host_identity': policy['surfaces']['ssh:ops-bastion']['strict_host_identity']
    },
    'archive:compliance': {
        'data_cipher': policy['surfaces']['archive:compliance']['data_cipher'],
        'wrap_algorithm': policy['surfaces']['archive:compliance']['wrap_algorithm'],
        'allowed_wrapping_keys': ['archive-wrap-hybrid-c'],
        'require_aead': policy['surfaces']['archive:compliance']['require_aead'],
        'require_hybrid_wrap': policy['surfaces']['archive:compliance']['require_hybrid_wrap']
    }
}

# Output intermediate to check
open('/app/submission/migration-plan.json', 'w').write(json.dumps({
    'format_version': 1,
    'case_id': estate['case_id'],
    'findings': {'compromised_material': compromised, 'retire_material': sorted(retire)},
    'dependencies': deps,
    'final_policies': final_policies,
    'actions': []
}, indent=2))
